using NUnit.Framework;
using VibraHeka.Application.Recordings.Queries.GetRecordingDownloadUrl;
using VibraHeka.Domain.Recordings.Errors;

namespace VibraHeka.Application.UnitTests.Recordings.Queries.GetRecordingDownloadUrl;

[TestFixture]
[NUnit.Framework.Category("Unit")]
public sealed class GetRecordingDownloadUrlQueryValidatorTest : GenericGetRecordingDownloadUrlTest
{
    private GetRecordingDownloadUrlQueryValidator RealValidator = default!;

    [SetUp]
    public override void SetUp()
    {
        base.SetUp();
        RealValidator = new GetRecordingDownloadUrlQueryValidator();
    }

    #region Empty / Whitespace RecordingId Tests

    [TestCase("", TestName = "Empty string")]
    [TestCase("   ", TestName = "Whitespace only")]
    [DisplayName("Should fail validation when RecordingId is empty or whitespace")]
    public void ShouldFailValidationWhenRecordingIdIsEmptyOrWhitespace(string recordingId)
    {
        // Given: a query with an empty or whitespace recording ID
        GetRecordingDownloadUrlQuery query = BuildValidQuery(recordingId);

        // When: validating the query
        TestValidationResult<GetRecordingDownloadUrlQuery> result = RealValidator.TestValidate(query);

        // Then: should have a validation error for RecordingId with InvalidRecordingId error code
        result.ShouldHaveValidationErrorFor(x => x.RecordingId)
            .WithErrorMessage(RecordingErrors.InvalidRecordingId);
    }

    #endregion

    #region Invalid GUID Format Tests

    [TestCase("not-a-guid", TestName = "Non-GUID string")]
    [TestCase("12345", TestName = "Numeric string")]
    [TestCase("abc-def-ghi-jkl", TestName = "Hyphenated non-GUID string")]
    [DisplayName("Should fail validation when RecordingId is not a valid GUID format")]
    public void ShouldFailValidationWhenRecordingIdIsNotValidGuid(string recordingId)
    {
        // Given: a query with an invalid (non-GUID format) recording ID
        GetRecordingDownloadUrlQuery query = BuildValidQuery(recordingId);

        // When: validating the query
        TestValidationResult<GetRecordingDownloadUrlQuery> result = RealValidator.TestValidate(query);

        // Then: should have a validation error for RecordingId with InvalidRecordingId error code
        result.ShouldHaveValidationErrorFor(x => x.RecordingId)
            .WithErrorMessage(RecordingErrors.InvalidRecordingId);
    }

    #endregion

    #region Happy Path Tests

    [Test]
    [DisplayName("Should pass validation when RecordingId is a valid GUID string")]
    public void ShouldPassValidationWhenRecordingIdIsValidGuid()
    {
        // Given: a query with a valid GUID recording ID
        GetRecordingDownloadUrlQuery query = BuildValidQuery(Guid.NewGuid().ToString());

        // When: validating the query
        TestValidationResult<GetRecordingDownloadUrlQuery> result = RealValidator.TestValidate(query);

        // Then: should not have any validation error for RecordingId
        result.ShouldNotHaveValidationErrorFor(x => x.RecordingId);
    }

    [Test]
    [DisplayName("Should pass validation when all fields are valid")]
    public void ShouldPassValidationWhenAllFieldsAreValid()
    {
        // Given: a query with all fields valid (generated by BuildValidQuery)
        GetRecordingDownloadUrlQuery query = BuildValidQuery();

        // When: validating the query
        TestValidationResult<GetRecordingDownloadUrlQuery> result = RealValidator.TestValidate(query);

        // Then: should not have any validation errors
        result.ShouldNotHaveAnyValidationErrors();
    }

    #endregion

    #region CascadeMode Tests

    [Test]
    [DisplayName("Should report exactly one error per field when CascadeMode is Stop")]
    public void ShouldReportExactlyOneErrorForRecordingIdWhenCascadeModeIsStop()
    {
        // Given: a query with an empty recording ID (triggers both NotEmpty and Must rules)
        GetRecordingDownloadUrlQuery query = BuildValidQuery("");

        // When: validating the query
        TestValidationResult<GetRecordingDownloadUrlQuery> result = RealValidator.TestValidate(query);

        // Then: should have exactly 1 error for RecordingId (CascadeMode.Stop stops after first failure)
        IEnumerable<ValidationFailure> idErrors = result.Errors
            .Where(e => e.PropertyName == nameof(GetRecordingDownloadUrlQuery.RecordingId))
            .ToList();

        Assert.That(idErrors.Count(), Is.EqualTo(1),
            $"Expected exactly 1 error for RecordingId with CascadeMode.Stop, but got {idErrors.Count()}");
        Assert.That(idErrors.First().ErrorMessage, Is.EqualTo(RecordingErrors.InvalidRecordingId),
            $"Expected error '{RecordingErrors.InvalidRecordingId}' but got: '{idErrors.First().ErrorMessage}'");
    }

    #endregion
}

using System.ComponentModel;
using Amazon.DynamoDBv2.DataModel;
using CSharpFunctionalExtensions;
using Infrastructure.Persistence.Catalog.Models;
using Moq;
using NUnit.Framework;
using VibraHeka.Domain.Catalog.Entities;
using VibraHeka.Domain.Catalog.Errors;
using VibraHeka.Infrastructure.Exceptions;

namespace VibraHeka.Infrastructure.UnitTests.Persistence.Repository.SellableItemRepositoryTest;

[TestFixture]
[NUnit.Framework.Category("Unit")]
public sealed class GetByReferenceIdAsyncTest : GenericSellableItemRepositoryTest
{
    [Test]
    [DisplayName("Should return mapped SellableItemEntity when DynamoDB returns a model for the reference ID")]
    public async Task ShouldReturnMappedEntityWhenDynamoDbReturnsModel()
    {
        // Given: DynamoDB returns a valid SellableItemDBModel for the requested reference ID
        string referenceId = Guid.NewGuid().ToString();
        SellableItemDBModel model = BuildDefaultSellableItemDBModel(referenceId);

        Mock<IAsyncSearch<SellableItemDBModel>> SearchMock = new();
        SearchMock
            .Setup(x => x.GetRemainingAsync(It.IsAny<CancellationToken>()))
            .ReturnsAsync([model]);

        ContextMock
            .Setup(x => x.QueryAsync<SellableItemDBModel>(
                referenceId,
                It.IsAny<QueryConfig>()))
            .Returns(SearchMock.Object);

        // When: GetByReferenceIdAsync is called
        Result<SellableItemEntity> result = await Repository.GetByReferenceIdAsync(referenceId, CancellationToken.None);

        // Then: result should be success with a correctly mapped entity
        Assert.That(result.IsSuccess, Is.True,
            $"Expected success but got failure with error: '{(result.IsSuccess ? "N/A" : result.Error)}'");
        Assert.That(result.Value.SellableItemID, Is.EqualTo(model.SellableItemID),
            $"Expected SellableItemID '{model.SellableItemID}' but got '{result.Value.SellableItemID}'");
        Assert.That(result.Value.Name, Is.EqualTo(model.Name),
            $"Expected Name '{model.Name}' but got '{result.Value.Name}'");
        Assert.That(result.Value.IsActive, Is.EqualTo(model.IsActive),
            $"Expected IsActive '{model.IsActive}' but got '{result.Value.IsActive}'");

        ContextMock.Verify(
            x => x.QueryAsync<SellableItemDBModel>(
                It.Is<string>(id => id == referenceId),
                It.Is<QueryConfig>(qc =>
                    qc.IndexName == "ReferenceId-Index" &&
                    qc.OverrideTableName == Config.SellableItemsTable)),
            Times.Once,
            $"Expected QueryAsync called once with indexName='ReferenceId-Index' and table='{Config.SellableItemsTable}'");

        SearchMock.Verify(
            x => x.GetRemainingAsync(It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected GetRemainingAsync called exactly once");

        ContextMock.VerifyNoOtherCalls();
        SearchMock.VerifyNoOtherCalls();
    }

    [Test]
    [DisplayName("Should return CAT-001 failure when DynamoDB returns an empty list (not found)")]
    public async Task ShouldReturnCAT001FailureWhenDynamoDbReturnsEmptyList()
    {
        // Given: DynamoDB returns an empty list — no SellableItem with that reference ID
        string referenceId = Guid.NewGuid().ToString();

        Mock<IAsyncSearch<SellableItemDBModel>> SearchMock = new();
        SearchMock
            .Setup(x => x.GetRemainingAsync(It.IsAny<CancellationToken>()))
            .ReturnsAsync([]);

        ContextMock
            .Setup(x => x.QueryAsync<SellableItemDBModel>(
                referenceId,
                It.IsAny<QueryConfig>()))
            .Returns(SearchMock.Object);

        // When: GetByReferenceIdAsync is called with a referenceId that has no results
        Result<SellableItemEntity> result = await Repository.GetByReferenceIdAsync(referenceId, CancellationToken.None);

        // Then: result should be failure with CAT-001 (mapped from GPE-000 NoRecordsFound)
        Assert.That(result.IsFailure, Is.True,
            $"Expected failure but got success with SellableItemID: '{(result.IsSuccess ? result.Value.SellableItemID : "N/A")}'");
        Assert.That(result.Error, Is.EqualTo(CatalogErrors.SellableItemNotFound),
            $"Expected error '{CatalogErrors.SellableItemNotFound}' (CAT-001) mapped from GPE-000, but got '{result.Error}'");

        ContextMock.Verify(
            x => x.QueryAsync<SellableItemDBModel>(
                It.Is<string>(id => id == referenceId),
                It.Is<QueryConfig>(qc => qc.IndexName == "ReferenceId-Index")),
            Times.Once,
            "Expected QueryAsync called exactly once before returning empty list");

        SearchMock.Verify(
            x => x.GetRemainingAsync(It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected GetRemainingAsync called exactly once");

        ContextMock.VerifyNoOtherCalls();
        SearchMock.VerifyNoOtherCalls();
    }

    [Test]
    [DisplayName("Should return CAT-003 failure when DynamoDB throws an unexpected exception")]
    public async Task ShouldReturnCAT003FailureWhenDynamoDbThrowsException()
    {
        // Given: DynamoDB throws an unexpected exception during the query
        string referenceId = Guid.NewGuid().ToString();

        ContextMock
            .Setup(x => x.QueryAsync<SellableItemDBModel>(
                referenceId,
                It.IsAny<QueryConfig>()))
            .Throws(new Exception("Unexpected DynamoDB connection error"));

        // When: GetByReferenceIdAsync is called
        Result<SellableItemEntity> result = await Repository.GetByReferenceIdAsync(referenceId, CancellationToken.None);

        // Then: result should be failure with CAT-003 (FailedToQuerySellableItem — non-NotFound errors map here)
        Assert.That(result.IsFailure, Is.True,
            "Expected failure when DynamoDB throws an unexpected exception");
        Assert.That(result.Error, Is.EqualTo(CatalogErrors.FailedToQuerySellableItem),
            $"Expected error '{CatalogErrors.FailedToQuerySellableItem}' (CAT-003) for general DynamoDB exception, but got '{result.Error}'");
        Assert.That(result.Error, Is.Not.EqualTo(CatalogErrors.SellableItemNotFound),
            "General exceptions must NOT be mapped to CAT-001; they must map to CAT-003");

        ContextMock.Verify(
            x => x.QueryAsync<SellableItemDBModel>(
                It.Is<string>(id => id == referenceId),
                It.Is<QueryConfig>(qc => qc.IndexName == "ReferenceId-Index")),
            Times.Once,
            "Expected QueryAsync called once before throwing the exception");

        ContextMock.VerifyNoOtherCalls();
    }
}

using Amazon;
using Amazon.S3;
using Moq;
using VibraHeka.Infrastructure.Entities;
using VibraHeka.Infrastructure.Persistence.S3;

namespace VibraHeka.Infrastructure.UnitTests.Persistence.S3.RecordingStorageRepositoryTest;

public abstract class GenericRecordingStorageRepositoryTest
{
    protected Mock<IAmazonS3> ClientMock = default!;
    protected AWSConfig Config = default!;
    protected RecordingStorageRepository Repository = default!;

    [SetUp]
    public virtual void SetUp()
    {
        ClientMock = new Mock<IAmazonS3>(MockBehavior.Loose);
        ClientMock
            .Setup(c => c.Config)
            .Returns(new AmazonS3Config { RegionEndpoint = RegionEndpoint.USEast1 });

        Config = new AWSConfig { RecordingsBucketName = "unit-test-recordings-bucket" };
        Repository = new RecordingStorageRepository(ClientMock.Object, Config);
    }
}

using System.ComponentModel;
using Amazon.S3.Model;
using CSharpFunctionalExtensions;
using Moq;

namespace VibraHeka.Infrastructure.UnitTests.Persistence.S3.RecordingStorageRepositoryTest;

[TestFixture]
[NUnit.Framework.Category("Unit")]
public sealed class GetDownloadUrlAsyncTest : GenericRecordingStorageRepositoryTest
{
    [Test]
    [DisplayName("Should extract S3 object key from full HTTPS URL and generate pre-signed URL")]
    public async Task ShouldExtractS3ObjectKeyFromFullUrlAndGeneratePreSignedUrl()
    {
        // Given: a storageKey that is a full S3 HTTPS URL — the repository must strip the host
        string recordingId = Guid.NewGuid().ToString();
        string fileName = "meditacion.mp4";
        string storageKey = $"https://{Config.RecordingsBucketName}.s3.us-east-1.amazonaws.com/{recordingId}/{fileName}";
        string expectedS3Key = $"{recordingId}/{fileName}";
        string preSignedUrl = "https://pre-signed-url.example.com/download?token=abc";

        ClientMock
            .Setup(c => c.GetPreSignedURLAsync(It.IsAny<GetPreSignedUrlRequest>()))
            .ReturnsAsync(preSignedUrl);

        // When: GetDownloadUrlAsync is called with the full URL storage key
        Result<string> result = await Repository.GetDownloadUrlAsync(storageKey, CancellationToken.None);

        // Then: result should be success and GetPreSignedURLAsync called with extracted key (not the full URL)
        Assert.That(result.IsSuccess, Is.True,
            $"Expected success but got failure with error: '{(result.IsSuccess ? "N/A" : result.Error)}'");
        Assert.That(result.Value, Is.EqualTo(preSignedUrl),
            $"Expected pre-signed URL '{preSignedUrl}' but got '{result.Value}'");

        ClientMock.Verify(
            c => c.GetPreSignedURLAsync(
                It.Is<GetPreSignedUrlRequest>(r =>
                    r.BucketName == Config.RecordingsBucketName &&
                    r.Key == expectedS3Key &&
                    r.Verb == Amazon.S3.HttpVerb.GET &&
                    r.Expires > DateTime.UtcNow)),
            Times.Once,
            $"Expected GetPreSignedURLAsync called once with BucketName='{Config.RecordingsBucketName}' and Key='{expectedS3Key}'");

        ClientMock.VerifyNoOtherCalls();
    }

    [Test]
    [DisplayName("Should use storageKey as-is when it is not a valid absolute URI (fallback path)")]
    public async Task ShouldUseStorageKeyAsIsWhenNotAValidAbsoluteUri()
    {
        // Given: a storageKey that is a plain relative path (not an absolute URI)
        string plainKey = "recordings/some-id/yoga.mp4";
        string preSignedUrl = "https://pre-signed-url.example.com/download?fallback=1";

        ClientMock
            .Setup(c => c.GetPreSignedURLAsync(It.IsAny<GetPreSignedUrlRequest>()))
            .ReturnsAsync(preSignedUrl);

        // When: GetDownloadUrlAsync is called with the plain key
        Result<string> result = await Repository.GetDownloadUrlAsync(plainKey, CancellationToken.None);

        // Then: result should be success and GetPreSignedURLAsync called with the original key unchanged
        Assert.That(result.IsSuccess, Is.True,
            $"Expected success but got failure with error: '{(result.IsSuccess ? "N/A" : result.Error)}'");
        Assert.That(result.Value, Is.EqualTo(preSignedUrl),
            $"Expected pre-signed URL '{preSignedUrl}' but got '{result.Value}'");

        ClientMock.Verify(
            c => c.GetPreSignedURLAsync(
                It.Is<GetPreSignedUrlRequest>(r =>
                    r.BucketName == Config.RecordingsBucketName &&
                    r.Key == plainKey &&
                    r.Verb == Amazon.S3.HttpVerb.GET)),
            Times.Once,
            $"Expected GetPreSignedURLAsync called once with the original key '{plainKey}' as fallback");

        ClientMock.VerifyNoOtherCalls();
    }

    [Test]
    [DisplayName("Should call GetPreSignedURLAsync with expiry of 3600 seconds")]
    public async Task ShouldCallGetPreSignedUrlWithExpiryOf3600Seconds()
    {
        // Given: any valid storage key
        string storageKey = $"recordings/{Guid.NewGuid()}/audio.mp3";
        string preSignedUrl = "https://pre-signed-url.example.com/download?expires=3600";
        DateTime beforeCall = DateTime.UtcNow;

        ClientMock
            .Setup(c => c.GetPreSignedURLAsync(It.IsAny<GetPreSignedUrlRequest>()))
            .ReturnsAsync(preSignedUrl);

        // When: GetDownloadUrlAsync is called
        Result<string> result = await Repository.GetDownloadUrlAsync(storageKey, CancellationToken.None);

        // Then: GetPreSignedURLAsync should have been called with Expires ≈ now + 3600 seconds
        DateTime expectedMinExpiry = beforeCall.AddSeconds(3600);
        DateTime expectedMaxExpiry = DateTime.UtcNow.AddSeconds(3600);

        Assert.That(result.IsSuccess, Is.True,
            $"Expected success but got failure: '{(result.IsSuccess ? "N/A" : result.Error)}'");

        ClientMock.Verify(
            c => c.GetPreSignedURLAsync(
                It.Is<GetPreSignedUrlRequest>(r =>
                    r.Expires >= expectedMinExpiry &&
                    r.Expires <= expectedMaxExpiry)),
            Times.Once,
            $"Expected GetPreSignedURLAsync called with Expires in range [{expectedMinExpiry:O}, {expectedMaxExpiry:O}] (3600 seconds from call time)");

        ClientMock.VerifyNoOtherCalls();
    }
}

"""Script to create all Catalog test files."""
import os

BASE = "/Users/pablo/Documents/Workspace/VibraHeka-backend"

def write_file(rel_path, content):
    full_path = os.path.join(BASE, rel_path)
    os.makedirs(os.path.dirname(full_path), exist_ok=True)
    with open(full_path, "w") as f:
        f.write(content)
    print(f"Created: {full_path}")

