write_file(
    "tests/Infrastructure.Rest.Client.IntegrationTests/Stripe/CatalogAdapterTest/GenericCatalogAdapterIntegrationTest.cs",
    """\
using System.ComponentModel.DataAnnotations;
using Infrastructure.Rest.Client.Stripe.Adapter;
using Infrastructure.Rest.Client.Stripe.Client;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using NUnit.Framework;
using Stripe;
using VibraHeka.Infrastructure.Entities;
using static System.ComponentModel.DataAnnotations.Validator;

namespace Infrastructure.Rest.Client.IntegrationTests.Stripe.CatalogAdapterTest;

/// <summary>
/// Base class for CatalogAdapter integration tests against the real Stripe test-mode API.
/// Reads StripeConfig from appsettings.Test.json and initialises StripeConfiguration.ApiKey.
/// All derived test fixtures must clean up any Stripe resources they create.
/// </summary>
public abstract class GenericCatalogAdapterIntegrationTest : TestBase
{
    protected CatalogAdapter Adapter = default!;
    protected StripeAPIClient StripeClient = default!;
    protected StripeConfig StripeConfig = default!;
    protected ProductService StripeProductService = default!;
    protected PriceService StripePriceService = default!;
    protected ILogger<CatalogAdapter> AdapterLogger = default!;

    [OneTimeSetUp]
    public void CatalogOneTimeSetUp()
    {
        base.OneTimeSetUp();
        StripeConfig = CreateStripeConfigFromSettings();
        StripeConfiguration.ApiKey = StripeConfig.SecretKey;
        StripeClient = new StripeAPIClient(CreateTestLogger<StripeAPIClient>());
        AdapterLogger = CreateTestLogger<CatalogAdapter>();
        Adapter = new CatalogAdapter(StripeClient, AdapterLogger);
        StripeProductService = new ProductService();
        StripePriceService = new PriceService();
    }

    private StripeConfig CreateStripeConfigFromSettings()
    {
        IConfigurationRoot config = new ConfigurationBuilder()
            .SetBasePath(AppContext.BaseDirectory)
            .AddJsonFile("appsettings.Test.json", optional: false)
            .AddEnvironmentVariables()
            .Build();

        StripeConfig stripeConfig = config.GetSection("Stripe").Get<StripeConfig>()
            ?? throw new InvalidOperationException("Missing Stripe config section.");

        ValidateObject(stripeConfig, new ValidationContext(stripeConfig), validateAllProperties: true);
        return stripeConfig;
    }

    /// <summary>
    /// Attempts to archive a Stripe price (prices cannot be deleted, only deactivated).
    /// Best-effort: logs warning on failure without failing the test.
    /// </summary>
    protected async Task CleanupStripePrice(string priceId)
    {
        try
        {
            await StripePriceService.UpdateAsync(priceId, new PriceUpdateOptions { Active = false });
            Console.WriteLine($"Cleanup: Archived Stripe price {priceId}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Warning: Could not archive Stripe price {priceId}: {ex.Message}");
        }
    }

    /// <summary>
    /// Attempts to delete a Stripe product. The product must have no active prices.
    /// Best-effort: logs warning on failure without failing the test.
    /// </summary>
    protected async Task CleanupStripeProduct(string productId)
    {
        try
        {
            await StripeProductService.DeleteAsync(productId);
            Console.WriteLine($"Cleanup: Deleted Stripe product {productId}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Warning: Could not delete Stripe product {productId}: {ex.Message}");
        }
    }
}
""",
)

write_file(
    "tests/Infrastructure.Rest.Client.IntegrationTests/Stripe/CatalogAdapterTest/CreateProductInGatewayAsyncIntegrationTest.cs",
    """\
using CSharpFunctionalExtensions;
using NMoneys;
using NUnit.Framework;
using VibraHeka.Application.Catalog.Models;
using VibraHeka.Domain.Catalog.Entities;

namespace Infrastructure.Rest.Client.IntegrationTests.Stripe.CatalogAdapterTest;

[TestFixture]
[NUnit.Framework.Category("Integration")]
public sealed class CreateProductInGatewayAsyncIntegrationTest : GenericCatalogAdapterIntegrationTest
{
    private string? CreatedProductId;
    private string? CreatedPriceId;

    [TearDown]
    public async Task TearDown()
    {
        // Cleanup in order: archive price first, then delete product (Stripe constraint)
        if (CreatedPriceId is not null)
        {
            await CleanupStripePrice(CreatedPriceId);
            CreatedPriceId = null;
        }

        if (CreatedProductId is not null)
        {
            await CleanupStripeProduct(CreatedProductId);
            CreatedProductId = null;
        }
    }

    [Test]
    [Description("Should return success with non-empty ProductGatewayID and ProductGatewayPriceID when Stripe test-mode creates a product and price")]
    public async Task ShouldReturnSuccessWithNonEmptyGatewayIdsWhenStripeCreatesProductAndPrice()
    {
        // Given: valid product and price entities
        ProductEntity productEntity = new ProductEntity
        {
            ProductID = Guid.NewGuid().ToString(),
            Name = $"Integration Test Product {Guid.NewGuid()}",
            Description = "Created by integration test - will be archived/deleted in TearDown",
        };
        SellableItemPriceEntity priceEntity = new SellableItemPriceEntity
        {
            SellableItemPriceID = Guid.NewGuid().ToString(),
            SellableItemID = Guid.NewGuid().ToString(),
            Amount = new Money(9.99m, CurrencyIsoCode.EUR),
        };

        // When: CreateProductInGatewayAsync is called against Stripe test-mode API
        Result<ProductGatewayCreatedResponseModel> result =
            await Adapter.CreateProductInGatewayAsync(productEntity, priceEntity, CancellationToken.None);

        // Capture IDs for TearDown cleanup (best-effort)
        if (result.IsSuccess)
        {
            CreatedProductId = result.Value.ProductGatewayID;
            CreatedPriceId = result.Value.ProductGatewayPriceID;
        }

        // Then: result must be success with non-empty gateway IDs
        Assert.That(result.IsSuccess, Is.True,
            $"Expected Stripe test-mode to succeed but got failure with error: '{(result.IsSuccess ? "N/A" : result.Error)}'");
        Assert.That(result.Value.ProductGatewayID, Is.Not.Null.And.Not.Empty,
            "Expected a non-empty ProductGatewayID from Stripe but got empty");
        Assert.That(result.Value.ProductGatewayPriceID, Is.Not.Null.And.Not.Empty,
            "Expected a non-empty ProductGatewayPriceID from Stripe but got empty");
        Assert.That(result.Value.ProductGatewayID, Does.StartWith("prod_"),
            $"Expected ProductGatewayID to start with 'prod_' but got: '{result.Value.ProductGatewayID}'");
        Assert.That(result.Value.ProductGatewayPriceID, Does.StartWith("price_"),
            $"Expected ProductGatewayPriceID to start with 'price_' but got: '{result.Value.ProductGatewayPriceID}'");
    }
}
""",
)

